/*! LUMINA Effects Studio – client-side runtime for effect browsing, parameters, favorites, and playback simulation */
(()=>{'use strict';const $=id=>document.getElementById(id),demo=location.protocol==='file:'||location.protocol==='content:';let EFFECT_CATALOG=[],state={effect:'solid',parameters:{},fps:60,transition_ms:200,favorites:[],running:false,power:true,led_count:24,brightness:128,max_brightness:128,color:{r:0,g:0,b:0},secondary:{r:0,g:0,b:0},hardware_ready:false},currentEffect=null,simulation={pixels:[],timer:null},pendingRequest=null,debounceTimer=null;function api(path,options={}){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),3500);return fetch(`/api/${path}`,{...options,signal:controller.signal,cache:'no-store'}).then(r=>r.json()).then(payload=>{clearTimeout(timeout);if(!payload.success||!payload.data)throw new Error(payload.error||'Invalid response');return payload.data}).catch(err=>{clearTimeout(timeout);throw err})}
function applyEffect(effectID,params={},transition=state.transition_ms){if(demo){state.effect=effectID;state.parameters=params;state.transition_ms=transition;statusMessage(`Effect set to ${effectID} (demo)`);simulateEffect(effectID,params);return Promise.resolve()}
const body={effect:effectID};if(transition!=null)body.transition_ms=transition;return api('led/effect',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(()=>{if(Object.keys(params).length>0){return updateParameters(params,transition)}}).then(()=>fetchState()).then(()=>statusMessage(`Effect "${effectID}" active`)).catch(e=>{statusError('Could not set effect: '+e.message);throw e})}
function updateParameters(params,transition=state.transition_ms){if(demo){Object.assign(state.parameters,params);statusMessage('Parameters updated (demo)');return Promise.resolve()}
const body={...params};if(transition!=null)body.transition_ms=transition;return api('led/parameters',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(()=>fetchState()).then(()=>statusMessage('Parameters updated')).catch(e=>statusError('Parameter update failed: '+e.message))}
function resetEffect(){if(demo){statusMessage('Effect reset (demo)');simulateEffect(state.effect,{});return Promise.resolve()}
return api('led/effect/reset',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}).then(()=>fetchState()).then(()=>statusMessage('Effect reset to defaults')).catch(e=>statusError('Reset failed: '+e.message))}
function stopEffect(){if(demo){state.effect='solid';state.running=false;statusMessage('Effect stopped (demo)');simulateEffect('solid',{});return Promise.resolve()}
return api('led/effect/stop',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}).then(()=>fetchState()).then(()=>statusMessage('Stopped, returned to solid')).catch(e=>statusError('Stop failed: '+e.message))}
function setFavorite(effectID,enabled){state.favorites=state.favorites.filter(id=>id!==effectID);if(enabled)state.favorites.push(effectID);if(!demo){updateParameters({favorite:{effect:effectID,enabled}}).catch(()=>{})}
renderCatalog()}
function fetchState(){if(demo)return Promise.resolve(state);return api('led/effect').catch(()=>api('led/parameters')).then(s=>{state=Object.assign(state,s);return state})}
function fetchEffects(){if(demo){EFFECT_CATALOG=[{id:'solid',name:'Solid',description:'Static color, no animation',category:'Static',preview:'',directional:false,colors:'single',parameters:[]},{id:'pulse',name:'Pulse',description:'Smooth fade in and out',category:'Animation',preview:'',directional:false,colors:'single',parameters:[{id:'speed',name:'Speed',min:1,max:100,default:50}]},{id:'chase',name:'Chase',description:'Running light pattern',category:'Animation',preview:'',directional:true,colors:'dual',parameters:[{id:'speed',name:'Speed',min:1,max:200,default:80},{id:'width',name:'Width',min:1,max:10,default:3}]},{id:'rainbow',name:'Rainbow',description:'Rotating rainbow cycle',category:'Pattern',preview:'',directional:false,colors:'none',parameters:[{id:'speed',name:'Speed',min:1,max:100,default:60}]}];statusMessage('Effect catalog loaded (demo)');renderCategories();renderCatalog();return Promise.resolve()}
return api('effects').then(catalog=>{EFFECT_CATALOG=Array.isArray(catalog)?catalog:(catalog.effects||[]);statusMessage(`${EFFECT_CATALOG.length} effects loaded`);renderCategories();renderCatalog()}).catch(e=>{statusError('Could not load effects: '+e.message);$('fx-retry').hidden=false})}
function renderCategories(){const select=$('fx-category'),previous=select.value;select.replaceChildren(new Option('All categories',''),...[...new Set(EFFECT_CATALOG.map(fx=>fx.category).filter(Boolean))].map(category=>new Option(category,category)));select.value=[...select.options].some(option=>option.value===previous)?previous:''}
function statusMessage(msg,error=false){$('fx-status').textContent=msg;$('fx-status').dataset.error=error}
function statusError(msg){statusMessage(msg,true)}
function renderCatalog(){const category=$('fx-category').value,favOnly=$('fx-filter').getAttribute('aria-pressed')==='true';let filtered=EFFECT_CATALOG;if(category)filtered=filtered.filter(fx=>fx.category===category);if(favOnly)filtered=filtered.filter(fx=>state.favorites.includes(fx.id));const list=$('fx-list'),empty=$('fx-empty');list.innerHTML='';if(filtered.length===0){empty.textContent=favOnly?'No favorites yet':'No effects match';empty.hidden=false;list.hidden=true;return}
empty.hidden=true;list.hidden=false;filtered.forEach(fx=>{const li=document.createElement('li'),btn=document.createElement('button');btn.type='button';btn.setAttribute('aria-pressed',fx.id===state.effect);btn.innerHTML=`<span class="fx-item"><span>${fx.name}</span><small>${fx.category||''}</small></span><span class="fx-star" aria-label="${state.favorites.includes(fx.id)?'Favorited':'Not favorited'}">${state.favorites.includes(fx.id)?'★':'☆'}</span>`;btn.addEventListener('click',()=>selectEffect(fx.id));li.appendChild(btn);list.appendChild(li)})}
function selectEffect(id){const fx=EFFECT_CATALOG.find(e=>e.id===id);if(!fx)return;currentEffect=fx;$('fx-name').textContent=fx.name;$('fx-description').textContent=fx.description;$('fx-favorite').setAttribute('aria-pressed',state.favorites.includes(id));$('fx-controls').disabled=false;renderParameters(fx.parameters||[]);applyEffect(id,{});renderCatalog()}
function renderParameters(params){const container=$('fx-parameters');container.innerHTML='';params.forEach(p=>{const wrap=document.createElement('div');wrap.className='fx-slider';const label=document.createElement('label'),out=document.createElement('output'),input=document.createElement('input');label.textContent=p.name;out.textContent=p.default;out.id=`fx-param-${p.id}-value`;input.type='range';input.id=`fx-param-${p.id}`;input.min=p.min;input.max=p.max;input.value=state.parameters[p.id]??p.default;input.setAttribute('aria-label',p.name);input.addEventListener('input',()=>{out.textContent=input.value;debounceUpdate({[p.id]:parseFloat(input.value)})});label.appendChild(document.createTextNode(' '));label.appendChild(out);wrap.appendChild(label);wrap.appendChild(input);container.appendChild(wrap)});const playback=$('fx-playback');playback.innerHTML='';const fpsWrap=document.createElement('div');fpsWrap.className='fx-slider';const fpsLabel=document.createElement('label'),fpsOut=document.createElement('output'),fpsInput=document.createElement('input');fpsLabel.textContent='FPS';fpsOut.textContent=state.fps||60;fpsOut.id='fx-param-fps-value';fpsInput.type='range';fpsInput.id='fx-param-fps';fpsInput.min='10';fpsInput.max='120';fpsInput.value=state.fps||60;fpsInput.setAttribute('aria-label','Frames per second');fpsInput.addEventListener('input',()=>{fpsOut.textContent=fpsInput.value;debounceUpdate({fps:parseInt(fpsInput.value,10)})});fpsLabel.appendChild(document.createTextNode(' '));fpsLabel.appendChild(fpsOut);fpsWrap.appendChild(fpsLabel);fpsWrap.appendChild(fpsInput);playback.appendChild(fpsWrap)}
function debounceUpdate(params){clearTimeout(debounceTimer);debounceTimer=setTimeout(()=>updateParameters(params),350)}
function simulateEffect(effectID,params){clearInterval(simulation.timer);const pixels=new Array(state.led_count).fill('#253043');const rail=$('fx-rail');rail.innerHTML='';for(let i=0;i<state.led_count;i++){const led=document.createElement('i');rail.appendChild(led)}
let frame=0;simulation.pixels=pixels;const animate=()=>{if(effectID==='solid'){pixels.fill(`rgb(${state.color.r},${state.color.g},${state.color.b})`)}else if(effectID==='pulse'){const phase=Math.sin((frame%(params.speed||50))/(params.speed||50)*Math.PI*2);const r=Math.floor(state.color.r*Math.abs(phase)),g=Math.floor(state.color.g*Math.abs(phase)),b=Math.floor(state.color.b*Math.abs(phase));pixels.fill(`rgb(${r},${g},${b})`)}else if(effectID==='chase'){const width=params.width||3,speed=params.speed||80;for(let i=0;i<pixels.length;i++){const pos=(i+Math.floor(frame/speed*10))%pixels.length;pixels[pos]=pos%10<width?`rgb(${state.color.r},${state.color.g},${state.color.b})`:'#253043'}}else if(effectID==='rainbow'){for(let i=0;i<pixels.length;i++){const hue=(i*360/pixels.length+frame*(params.speed||60)/10)%360;pixels[i]=`hsl(${hue},100%,50%)`}}
rail.querySelectorAll('i').forEach((led,i)=>{led.style.background=pixels[i]||'#253043'});frame++};animate();simulation.timer=setInterval(animate,1000/(state.fps||60))}
$('fx-category').addEventListener('change',renderCatalog);$('fx-filter').addEventListener('click',e=>{const pressed=e.target.getAttribute('aria-pressed')==='true';e.target.setAttribute('aria-pressed',!pressed);renderCatalog()});$('fx-favorite').addEventListener('click',()=>{if(!currentEffect)return;const fav=state.favorites.includes(currentEffect.id);setFavorite(currentEffect.id,!fav);$('fx-favorite').setAttribute('aria-pressed',!fav)});$('fx-reset').addEventListener('click',resetEffect);$('fx-stop').addEventListener('click',stopEffect);$('fx-retry').addEventListener('click',()=>{$('fx-retry').hidden=true;fetchEffects()});window.Effects={refresh:fetchState,reload:fetchEffects};document.addEventListener('DOMContentLoaded',()=>{fetchState().catch(()=>{}).then(fetchEffects)});})();
